	private static String publishGrowth(SailRepository repository) {
		// Namespace publication consumes TripleStore capacity, independently of dictionary payload sizes.
		String namespace = "urn:checkpoint-contract:growth:" + "n".repeat(Math.toIntExact(MAP_SIZE * 15 / 100));
		try (RepositoryConnection writer = repository.getConnection()) {
			writer.begin(IsolationLevels.SNAPSHOT);
			writer.setNamespace("checkpoint-growth", namespace);
			for (int i = 0; i < 10_000; i++) {
				writer.add(VF.createIRI("urn:checkpoint-contract:growth:" + i), VF.createIRI(GROWTH_PREDICATE),
						VF.createLiteral("growth"));
			}
			writer.add(VF.createIRI("urn:checkpoint-contract:subject:64"), VF.createIRI(PREDICATE),
					VF.createLiteral(64));
			writer.commit();
		}
		return namespace;
	}

	private static String checkpointProgressState(OrderBarrierFunction function, GrowthNotificationBarrier notification,
			Future<?> query) {
		Thread reader = function.comparatorThread.get();
		Thread holder = notification.holder.get();
		ThreadInfo state = reader == null ? null
				: ManagementFactory.getThreadMXBean().getThreadInfo(reader.threadId(), Integer.MAX_VALUE);
		return "calls=" + function.calls.get() + "; queryDone=" + query.isDone() + "; reader=" + state
				+ "; readerStack=" + (state == null ? "unavailable" : Arrays.toString(state.getStackTrace()))
				+ "; notifier=" + holder + "; notifierVirtual=" + (holder != null && holder.isVirtual())
				+ "; notifierReturned=" + notification.returned.get();
	}

	private static void awaitReplayAccepted(LmdbSailStore store, MapGrowthMetrics.Snapshot before) {
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(FIXTURE_TIMEOUT_SECONDS);
		while (store.growthMetricsSnapshot().replayAccepted() <= before.replayAccepted()) {
			assertTrue(System.nanoTime() < deadline,
					"The released growth notification must publish a real replay request");
			Thread.yield();
		}
	}

	private static void await(CountDownLatch latch, String message) throws InterruptedException {
		assertTrue(latch.await(FIXTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS), message);
	}

	private static final class GrowthNotificationBarrier {
		private final AtomicReference<Thread> queryThread = new AtomicReference<>();
		private final AtomicReference<LmdbStoreConnection> reader = new AtomicReference<>();
		private final AtomicReference<Thread> holder = new AtomicReference<>();
		private final AtomicBoolean armed = new AtomicBoolean();
		private final AtomicBoolean paused = new AtomicBoolean();
		private final AtomicBoolean returned = new AtomicBoolean();
		private final CountDownLatch entered = new CountDownLatch(1);
		private final CountDownLatch release = new CountDownLatch(1);

		private void beforeIsolationRead(LmdbStoreConnection connection) {
			if (connection != reader.get() || !armed.get() || paused.get()) {
				return;
			}
			boolean notifyingGrowth = StackWalker.getInstance()
					.walk(frames -> frames
							.anyMatch(frame -> frame.getClassName().equals(LmdbStoreConnection.class.getName())
									&& frame.getMethodName().equals("requestReplayForMapGrowth")));
			if (notifyingGrowth && paused.compareAndSet(false, true)) {
				// This normal isolation getter is called under readAttemptLock before exposure.requestGrowth.
				holder.set(Thread.currentThread());
				entered.countDown();
				try {
					// The owner guard must outlive the progress guard, so only the test can release this monitor.
					assertTrue(release.await(2 * FIXTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS),
							"The test must release its actual growth notification");
				} catch (InterruptedException failure) {
					Thread.currentThread().interrupt();
					throw new SailException(failure);
				} finally {
					returned.set(true);
				}
			}
		}
	}

	private static final class OrderBarrierFunction implements Function {
		private final String uri;
		private final AtomicInteger calls = new AtomicInteger();
		private final AtomicReference<Thread> comparatorThread = new AtomicReference<>();
		private final AtomicReference<CloseableIteration<? extends Statement>> retainedStatements = new AtomicReference<>();
		private final CountDownLatch firstComparison = new CountDownLatch(1);
		private final CountDownLatch releaseFirst = new CountDownLatch(1);
		private final CountDownLatch nextComparison = new CountDownLatch(1);
		private final CountDownLatch releaseNext = new CountDownLatch(1);

		private OrderBarrierFunction(String uri) {
			this.uri = uri;
		}

		@Override
		public String getURI() {
			return uri;
		}

		@Override
		public Value evaluate(TripleSource tripleSource, Value... args) throws ValueExprEvaluationException {
			if (calls.get() == 0) {
				// ORDER has buffered its input. Keep a real nested cursor alive so the growth observer has an
				// affected native view to notify while this admitted application comparison is paused.
				CloseableIteration<? extends Statement> statements = tripleSource.getStatements(null,
						VF.createIRI(PREDICATE), null);
				retainedStatements.set(statements);
				assertTrue(statements.hasNext(), "The nested callback must retain an actual native statement view");
			}
			return evaluate(tripleSource.getValueFactory(), args);
		}

		@Override
		public Value evaluate(ValueFactory valueFactory, Value... args) throws ValueExprEvaluationException {
			int invocation = calls.incrementAndGet();
			if (invocation == 1 || invocation == 3) {
				boolean comparing = StackWalker.getInstance()
						.walk(frames -> frames
								.anyMatch(frame -> frame.getClassName().equals(OrderComparator.class.getName())
										&& frame.getMethodName().equals("compare")));
				assertTrue(comparing, "The checkpoint fixture must pause an actual ORDER comparator operand");
				comparatorThread.set(Thread.currentThread());
				(invocation == 1 ? firstComparison : nextComparison).countDown();
				try {
					assertTrue((invocation == 1 ? releaseFirst : releaseNext)
							.await(2 * FIXTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS),
							"The test must release the paused comparator operand");
				} catch (InterruptedException failure) {
					Thread.currentThread().interrupt();
					throw new ValueExprEvaluationException(failure);
				}
				if (invocation == 3) {
					closeRetainedStatements();
				}
			}
			return args[0];
		}

		private void closeRetainedStatements() {
			CloseableIteration<? extends Statement> statements = retainedStatements.getAndSet(null);
			if (statements != null) {
				statements.close();
			}
		}
	}
